const text = $input.first().json.output || '';
let parsed;
try {
  // Strip any accidental markdown backticks like ```json ... ```
  const clean = text.replace(/```json/gi, '').replace(/```/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = {
    confidence_score: 0.20,
    root_cause: "Unknown / Parse failure",
    suggested_fix: text,
    citations: [],
    reason_for_confidence: "AI response was not valid JSON"
  };
}

return parsed;

